(* [comment removed for export] *)
Lemma centryM (R : bvmap 5 word) M LBq LK cr Aw VM (X h : Z) :
  getr R (reg 1) = Z_to_bv 64 X -> L5.ra_ok X -> getr R (reg 2) = Z_to_bv 64 (S - 80) -> kept_rs R -> memrel M -> ri_inv HI LBq FF LK cr Aw M VM -> incl LK LK0 -> 0 <= h <= 5 ->
