Lemma centry (R : bvmap 5 word) M model src x g sm cr LK Aw (X h : Z) :
  getr R (reg 1) = Z_to_bv 64 X -> L5.ra_ok X -> getr R (reg 2) = Z_to_bv 64 (S - 80) -> kept_rs R -> st_ok M model src x g sm cr LK Aw -> 0 <= h <= 5 ->
  PMSPA.entryA AD L ar R M (S - 80) X h /\ PGSA.ffroomB PNRA.FCB h FF LK /\ PMSPA.ffrsA FF (S - 80).
Proof using All.
