Definition pbl_specG (pc h : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r o c cc n0 p : Z),
    ri_inv HI ((p, cc) :: LB) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA A L ar R M sp r h -> PGSA.ffroomB PQRA.FCM h FF LK -> PMSPA.ffrsA FF sp -> sp mod 16 = 0 ->
    getr R (reg 10) = Z_to_bv 64 o -> getr R (reg 11) = Z_to_bv 64 c -> 0 <= c < 256 ->
    PMSPA.aobjA FF o 24 -> o mod 8 = 0 -> PM.vstr_at segs PMSPA.accA M o (PM.VLong cc n0 p) -> n0 + 1 < cc -> n0 < 2 ^ 26 ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe),
        regs_preserved R R' ->
        PM.vstr_at segs PMSPA.accA M' o (PM.VLong cc (n0 + 1) p) -> L5.u8_at segs M' (p + n0) c -> L5.u8_at segs M' (p + n0 + 1) 0 ->
        L5CA.ahpres L ar LB FF sp (PMSPA.pm_scr h) [(o, 24)] M M' ->
        model_rt model model' -> incl LK' LK -> L5CA.amodel_ok Aw model' ->
        ri_inv HI ((p, cc) :: LB) FF LK' cr Aw M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.
End Specs.

